function validate([root]) {
  if (!Array.isArray(root)) return 'root is a list of values with null closing each group of children.';
  if (root.length === 0) return null;
  if (!Number.isInteger(root[0])) return 'The array must start with the root value.';
  if (root.length > 1 && root[1] !== null) return 'The root value must be followed by a null.';
  const depth = [1];
  let parent = 0;
  let i = 2;
  while (i < root.length) {
    if (parent >= depth.length) return 'Each group of children needs a parent node before it.';
    while (i < root.length && root[i] !== null) {
      if (!Number.isInteger(root[i])) return 'Node values are integers.';
      depth.push(depth[parent] + 1);
      i++;
    }
    i++;
    parent++;
  }
  if (root.some(v => v !== null && (v < 0 || v > 10000))) return 'Node values are between 0 and 10^4.';
  if (depth.length > 10000) return 'The tree has at most 10^4 nodes.';
  if (Math.max(...depth) > 1000) return 'The tree is at most 1000 levels high.';
  return null;
}

adapter:
function adapt(input, solve, kit) {
  const [values] = input;
  class Node {
    constructor(val, children = []) { this.val = val; this.children = children; }
  }
  // Rebuild the tree: after the root and its null, each group closed by a null belongs to the next node in breadth-first order.
  const root = values.length > 0 ? new Node(values[0]) : null;
  const queue = root ? [root] : [];
  let i = 2;
  for (let head = 0; head < queue.length && i < values.length; head++) {
    while (i < values.length && values[i] !== null) {
      const child = new Node(values[i]);
      queue[head].children.push(child);
      queue.push(child);
      i++;
    }
    i++;
  }
  const result = solve(root);
  if (!Array.isArray(result)) throw new Error('The solution must return an array of values.');
  return result;
}

