function postorder(root) {
  // Iterative: visit node, then children right to left, which yields reversed postorder.
  if (!root) return [];
  const out = [];
  const stack = [root];
  while (stack.length) {
    const node = stack.pop();
    out.push(node.val);
    for (const child of node.children) stack.push(child);
  }
  return out.reverse();
}

