function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const n = size === 'large' ? 900 + pick(99) : pick(12);
  if (n === 0) return [[]];
  const deep = rand() < 0.4;
  const span = size === 'large' ? 10001 : 30;
  const nodes = [{ val: pick(span), children: [] }];
  while (nodes.length < n) {
    // Deep trees grow from the newest nodes; bushy trees attach a child anywhere.
    const parent = deep ? nodes[Math.max(0, nodes.length - 1 - pick(3))] : nodes[pick(nodes.length)];
    const child = { val: pick(span), children: [] };
    parent.children.push(child);
    nodes.push(child);
  }
  const out = [nodes[0].val, null];
  const queue = [nodes[0]];
  for (let head = 0; head < queue.length; head++) {
    for (const child of queue[head].children) {
      out.push(child.val);
      queue.push(child);
    }
    out.push(null);
  }
  while (out[out.length - 1] === null) out.pop();
  return [out];
}
